				NBTTagCompound data = new NBTTagCompound();
				data.setBoolean("deconstruct", true);
				PacketDispatcher.wrapper.sendToServer(new NBTControlPacket(data, machine.getPos().getX(), machine.getPos().getY(), machine.getPos().getZ()));
			}
		}
	}

